        "title": "全国先进基层党组织、全国民主法治示范村（社区）、全国示范性老年友好型社区、全国综合减灾示范社区",
        "summary": `光明社区成立于2007年7月，隶属于南昌市东湖区彭家桥街道，以南昌发电厂家属区为主体，辖区面积12.5万平方米，居民1677户4191人，其中60岁以上老人1078人、党员276名。社区深入贯彻习近平总书记视察重要指示精神，聚焦为老服务，获评“全国先进基层党组织”等100余项市级以上荣誉，50余次被中央媒体报道。
光明社区打造适老化宜居环境，建成“15分钟生活圈”，完善居家养老服务中心等配套，推行“一户一策”适老化改造。以“1+X”志愿服务为抓手，联合卫生服务中心提供健康管理、家庭医生签约等服务；推进科技助老，开展智慧培训跨越数字鸿沟，通过线上网格群实现“点单接单”便民服务；依托各类阵地开展文体活动，打造19类特色品牌项目及孝老文化长廊，丰富居民精神生活，切实实现老年人“老有所依、老有所养、老有所安、老有所乐”。`
